local PulleyMaker = {}
local PRODUCTS = {
    simple_wood_pulley = { name = "Preprost leseno škripec", woodCost = 3, ironCost = 1, ropeCost = 1, time = 4, cost = 80, science = 18, happiness = 1, description = "Preprost leseno škripec za dviganje." },
    iron_bushed_pulley = { name = "Železnoležajni škripec", woodCost = 2, ironCost = 2, brassCost = 1, ropeCost = 1, time = 6, cost = 220, science = 32, happiness = 1, prestige = 2, description = "Železnoležajni škripec za trgovce." },
    silver_axle_pulley = { name = "Srebrnaosni škripec", woodCost = 2, ironCost = 2, silverCost = 1, brassCost = 1, ropeCost = 1, time = 9, cost = 540, science = 48, happiness = 2, prestige = 6, description = "Srebrnaosni škripec za plemiče." },
    gold_trimmed_pulley = { name = "Zlatookrasni škripec", woodCost = 2, ironCost = 2, goldCost = 1, silverCost = 1, brassCost = 1, ropeCost = 1, time = 13, cost = 1300, science = 62, happiness = 3, prestige = 14, description = "Zlatookrasni škripec za visoke plemiče." },
    jewel_set_pulley = { name = "Draguljasta škripec", woodCost = 2, ironCost = 2, goldCost = 1, silverCost = 1, brassCost = 1, ropeCost = 1, jewelCost = 1, time = 17, cost = 2900, science = 78, happiness = 5, prestige = 27, description = "Škripec z draguljem za visoko plemstvo." },
    royal_grand_pulley = { name = "Kraljevski veliki škripec", woodCost = 3, ironCost = 3, goldCost = 2, silverCost = 2, brassCost = 1, ropeCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 6200, science = 95, happiness = 12, prestige = 58, description = "Veliki kraljevski škripec z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    pulley_workshop = { name = "Škripčna delavnica", cost = { gold = 260, wood = 140, stone = 120, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    machinery_loft = { name = "Strojna podstrešje", cost = { gold = 950, wood = 280, stone = 280, silver = 6, brass = 6 }, upkeep = 22, qualityBonus = 18 },
    master_mechanic_atelier = { name = "Mojstrski mehanični atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_machinery_palace = { name = "Kraljevska strojna palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
PulleyMaker.woodStock = 18; PulleyMaker.ironStock = 14; PulleyMaker.brassStock = 10; PulleyMaker.ropeStock = 10; PulleyMaker.silverStock = 6; PulleyMaker.goldStock = 6; PulleyMaker.jewelStock = 4; PulleyMaker.pearlStock = 4
PulleyMaker.productStock = {}; PulleyMaker.buildings = {}; PulleyMaker.maker = nil; PulleyMaker.activeMaking = {}; PulleyMaker.totalProducts = 0; PulleyMaker.dayTimer = 0
function PulleyMaker.init() PulleyMaker.woodStock=18; PulleyMaker.ironStock=14; PulleyMaker.brassStock=10; PulleyMaker.ropeStock=10; PulleyMaker.silverStock=6; PulleyMaker.goldStock=6; PulleyMaker.jewelStock=4; PulleyMaker.pearlStock=4; PulleyMaker.productStock={}; PulleyMaker.buildings={}; PulleyMaker.maker=nil; PulleyMaker.activeMaking={}; PulleyMaker.totalProducts=0; PulleyMaker.dayTimer=0; print("[PulleyMaker] Royal Pulley Maker System initialized (6 products, 4 buildings)") end
function PulleyMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PulleyMaker.maker={name=n or ("Škripčar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škripčar najet: %s (spretnost: %d)",PulleyMaker.maker.name,s),"success") end; return true end
function PulleyMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PulleyMaker.build(id) local ok,e=PulleyMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PulleyMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PulleyMaker.getQualityBonus() local b=0; for _,bd in ipairs(PulleyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PulleyMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and PulleyMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and PulleyMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and PulleyMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.ropeCost and PulleyMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and PulleyMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PulleyMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PulleyMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PulleyMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PulleyMaker.buildings==0 then return false,"Potrebna škripčna delavnica" end; if not PulleyMaker.maker then return false,"Potreben škripčar" end; return true end
function PulleyMaker.make(pt,qty) qty=qty or 1; local ok,e=PulleyMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then PulleyMaker.woodStock=PulleyMaker.woodStock-d.woodCost*qty end; if d.ironCost then PulleyMaker.ironStock=PulleyMaker.ironStock-d.ironCost*qty end; if d.brassCost then PulleyMaker.brassStock=PulleyMaker.brassStock-d.brassCost*qty end; if d.ropeCost then PulleyMaker.ropeStock=PulleyMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then PulleyMaker.silverStock=PulleyMaker.silverStock-d.silverCost*qty end; if d.goldCost then PulleyMaker.goldStock=PulleyMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PulleyMaker.jewelStock=PulleyMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PulleyMaker.pearlStock=PulleyMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PulleyMaker.maker then t=math.max(1,t-math.floor(PulleyMaker.maker.skill/13)) end; table.insert(PulleyMaker.activeMaking,{id="pulley_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PulleyMaker.completeMaking(m) local q=1.0+(PulleyMaker.getQualityBonus()/100); if PulleyMaker.maker then q=q+(PulleyMaker.maker.skill/140) end; q=math.min(2.5,q); PulleyMaker.productStock[m.productType]=(PulleyMaker.productStock[m.productType] or 0)+m.quantity; PulleyMaker.totalProducts=PulleyMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PulleyMaker.maker then PulleyMaker.maker.itemsMade=PulleyMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PulleyMaker.maker.skill=math.min(100,PulleyMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škripec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pulley.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function PulleyMaker.update(dt) if not _G.state then return end; PulleyMaker.dayTimer=PulleyMaker.dayTimer+dt; if PulleyMaker.dayTimer>=30 then PulleyMaker.dayTimer=0; for i=#PulleyMaker.activeMaking,1,-1 do local m=PulleyMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PulleyMaker.completeMaking(m); table.remove(PulleyMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PulleyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PulleyMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PulleyMaker.getStats() return {woodStock=PulleyMaker.woodStock,ironStock=PulleyMaker.ironStock,brassStock=PulleyMaker.brassStock,ropeStock=PulleyMaker.ropeStock,silverStock=PulleyMaker.silverStock,goldStock=PulleyMaker.goldStock,jewelStock=PulleyMaker.jewelStock,pearlStock=PulleyMaker.pearlStock,productStock=PulleyMaker.productStock,numBuildings=#PulleyMaker.buildings,hasMaker=PulleyMaker.maker~=nil,makerName=PulleyMaker.maker and PulleyMaker.maker.name or "—",makerSkill=PulleyMaker.maker and PulleyMaker.maker.skill or 0,activeMaking=#PulleyMaker.activeMaking,totalProducts=PulleyMaker.totalProducts} end
return PulleyMaker
